// What a program does about a value that may not be there.
library {
    // Read an optional value by naming both cases: `fallback` when there is
    // nothing, `present` applied to what is there when there is.
    //
    // `Option`'s own recursor, written where a program can reach it. A total
    // language has no way to unwrap one without saying what happens when it is
    // empty, so this is the only way to read an `Option` and it is two lines.
    fn option_fold<A, B>(fallback: B, present: A -> B, value: Option<A>) -> B {
        match value {
            None -> fallback,
            Some(held) -> present(held),
        }
    }

    // Read an optional pitch, using fallback when it is absent and present
    // when it is available.
    fn pitch_or_else(fallback: Pitch, present: Pitch -> Pitch, value: Option<Pitch>) -> Pitch {
        option_fold(fallback, present, value)
    }

    // Read an optional natural number under the same explicit policy.
    fn nat_or_else(fallback: Nat, present: Nat -> Nat, value: Option<Nat>) -> Nat {
        option_fold(fallback, present, value)
    }
}
